#include "linux_wayland.h"
#include "window/window_inc.h"

#include <wayland-client.h>

// Generated by wayland-scanner in build.sh
#include "generated/xdg-shell-client-protocol.h"
#include "generated/xdg-shell-protocol.c"

#define WL_COMPOSITOR_MAX_VERSION 4
#define XDG_WM_BASE_VERSION 1
#define WL_SHM_VERSION 1

#define BYTES_PER_PIXEL 4

static void registry_global(void *data, struct wl_registry *registry, u32 name,
                            const char *interface, u32 version)
{
    linux_wayland_window_t *window = data;

    if (0 == strcmp(interface, wl_compositor_interface.name)) {
        u32 v = MIN(version, WL_COMPOSITOR_MAX_VERSION);
        window->compositor = wl_registry_bind(registry, name, &wl_compositor_interface, v);
    } else if (0 == strcmp(interface, wl_shm_interface.name)) {
        window->shm = wl_registry_bind(registry, name, &wl_shm_interface, WL_SHM_VERSION);
    } else if (0 == strcmp(interface, xdg_wm_base_interface.name)) {
        window->wm_base =
            wl_registry_bind(registry, name, &xdg_wm_base_interface, XDG_WM_BASE_VERSION);
    }
}

static void registry_global_remove(void *data, struct wl_registry *registry, u32 name)
{
    (void)data;
    (void)registry;
    (void)name;
}

static const struct wl_registry_listener registry_listener = {
    .global = registry_global,
    .global_remove = registry_global_remove,
};

static void wm_base_ping(void *data, struct xdg_wm_base *wm_base, u32 serial)
{
    (void)data;
    xdg_wm_base_pong(wm_base, serial);
}

static const struct xdg_wm_base_listener wm_base_listener = {
    .ping = wm_base_ping,
};

static void xdg_surface_configure(void *data, struct xdg_surface *xdg_surface, u32 serial)
{
    linux_wayland_window_t *window = data;
    xdg_surface_ack_configure(xdg_surface, serial);
    window->configured = true;
    window->base.needs_redraw = true;
}

static const struct xdg_surface_listener xdg_surface_listener = {
    .configure = xdg_surface_configure,
};

static void xdg_toplevel_configure(void *data, struct xdg_toplevel *toplevel, i32 width,
                                   i32 height, struct wl_array *states)
{
    (void)toplevel;
    (void)states;
    linux_wayland_window_t *window = data;

    if (width > 0 && height > 0) {
        window->base.width = width;
        window->base.height = height;
    }
}

static void xdg_toplevel_close(void *data, struct xdg_toplevel *toplevel)
{
    (void)toplevel;
    linux_wayland_window_t *window = data;
    window->base.should_close = true;
}

static const struct xdg_toplevel_listener xdg_toplevel_listener = {
    .configure = xdg_toplevel_configure,
    .close = xdg_toplevel_close,
};

static void frame_done(void *data, struct wl_callback *callback, u32 time)
{
    (void)time;
    linux_wayland_window_t *window = data;
    wl_callback_destroy(callback);
    window->frame_callback = NULL;
    window->base.needs_redraw = true;
}

static const struct wl_callback_listener frame_listener = {
    .done = frame_done,
};

static void buffer_release(void *data, struct wl_buffer *buffer)
{
    (void)buffer;
    linux_wayland_buffer_t *slot = data;
    slot->busy = false;
}

static const struct wl_buffer_listener buffer_listener = {
    .release = buffer_release,
};

static void buffer_destroy(linux_wayland_buffer_t *slot)
{
    if (slot->buffer)
        wl_buffer_destroy(slot->buffer);
    if (slot->framebuffer.pixels)
        munmap(slot->framebuffer.pixels, slot->size);
    *slot = (linux_wayland_buffer_t){};
}

static bool buffer_create(linux_wayland_window_t *window, linux_wayland_buffer_t *slot)
{
    i32 width = window->base.width;
    i32 height = window->base.height;
    i32 stride = width * BYTES_PER_PIXEL;
    usize size = (usize)stride * (usize)height;

    int fd = memfd_create(window->base.title, MFD_CLOEXEC);
    if (-1 == fd) {
        return false;
    }
    if (-1 == ftruncate(fd, (off_t)size)) {
        close(fd);
        return false;
    }

    u32 *pixels = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (MAP_FAILED == pixels) {
        close(fd);
        return false;
    }

    struct wl_shm_pool *pool = wl_shm_create_pool(window->shm, fd, (i32)size);
    slot->buffer =
        wl_shm_pool_create_buffer(pool, 0, width, height, stride, WL_SHM_FORMAT_XRGB8888);
    wl_shm_pool_destroy(pool);
    close(fd);

    wl_buffer_add_listener(slot->buffer, &buffer_listener, slot);
    slot->framebuffer = (framebuffer_t){
        .pixels = pixels,
        .width = width,
        .height = height,
        .stride = stride,
    };
    slot->size = size;
    slot->busy = false;
    return true;
}

static linux_wayland_buffer_t *buffer_acquire(linux_wayland_window_t *window)
{
    linux_wayland_buffer_t *slot = NULL;
    while (NULL == slot) {
        for (usize i = 0; i < LINUX_WAYLAND_BUFFER_COUNT; i++) {
            if (!window->buffers[i].busy) {
                slot = &window->buffers[i];
                break;
            }
        }
        if (NULL == slot && -1 == wl_display_dispatch(window->display)) {
            window->base.should_close = true;
            return NULL;
        }
    }

    // Dispatching above may have changed the window size, so compare only now
    if (slot->framebuffer.width != window->base.width ||
        slot->framebuffer.height != window->base.height) {
        buffer_destroy(slot);
        if (!buffer_create(window, slot)) {
            LOG_ERROR("cannot create the shm buffer");
            window->base.should_close = true;
            return NULL;
        }
    }
    return slot;
}

void window_destroy(window_t *base)
{
    if (NULL == base) {
        return;
    }
    linux_wayland_window_t *window = CONTAINER_OF(base, linux_wayland_window_t, base);

    if (window->xdg_toplevel)
        xdg_toplevel_destroy(window->xdg_toplevel);
    if (window->xdg_surface)
        xdg_surface_destroy(window->xdg_surface);
    if (window->surface)
        wl_surface_destroy(window->surface);
    if (window->frame_callback)
        wl_callback_destroy(window->frame_callback);
    for (usize i = 0; i < LINUX_WAYLAND_BUFFER_COUNT; i++) {
        buffer_destroy(&window->buffers[i]);
    }
    if (window->shm)
        wl_shm_destroy(window->shm);
    if (window->wm_base)
        xdg_wm_base_destroy(window->wm_base);
    if (window->compositor)
        wl_compositor_destroy(window->compositor);
    if (window->registry)
        wl_registry_destroy(window->registry);
    if (window->display)
        wl_display_disconnect(window->display);

    *window = (linux_wayland_window_t){};
}

window_t *window_create(arena_t *arena, window_params_t params)
{
    linux_wayland_window_t *window = PUSH_STRUCT(arena, linux_wayland_window_t);
    *window = (linux_wayland_window_t){
        .base = {
            .title = params.title,
            .width = params.width,
            .height = params.height,
        },
    };

    window->display = wl_display_connect(NULL);
    if (NULL == window->display) {
        LOG_ERROR("cannot connect to the wayland display");
        goto fail;
    }

    window->registry = wl_display_get_registry(window->display);
    wl_registry_add_listener(window->registry, &registry_listener, window);

    wl_display_roundtrip(window->display);

    if (NULL == window->compositor || NULL == window->shm || NULL == window->wm_base) {
        LOG_ERROR("compositor lacks wl_compositor, wl_shm or xdg_wm_base");
        goto fail;
    }
    xdg_wm_base_add_listener(window->wm_base, &wm_base_listener, window);

    window->surface = wl_compositor_create_surface(window->compositor);
    window->xdg_surface = xdg_wm_base_get_xdg_surface(window->wm_base, window->surface);
    xdg_surface_add_listener(window->xdg_surface, &xdg_surface_listener, window);

    window->xdg_toplevel = xdg_surface_get_toplevel(window->xdg_surface);
    xdg_toplevel_add_listener(window->xdg_toplevel, &xdg_toplevel_listener, window);
    xdg_toplevel_set_title(window->xdg_toplevel, params.title);
    xdg_toplevel_set_app_id(window->xdg_toplevel, params.title);

    wl_surface_commit(window->surface);
    while (!window->configured) {
        if (-1 == wl_display_dispatch(window->display)) {
            LOG_ERROR("lost connection waiting for first configure");
            goto fail;
        }
    }

    // Buffers are created on the first window_framebuffer
    // The window only becomes visible on the first window_present
    return &window->base;

fail:
    window_destroy(&window->base);
    return NULL;
}

framebuffer_t window_framebuffer(window_t *base)
{
    linux_wayland_window_t *window = CONTAINER_OF(base, linux_wayland_window_t, base);
    window->current = buffer_acquire(window);
    if (NULL == window->current) {
        return (framebuffer_t){};
    }
    base->needs_redraw = false;
    return window->current->framebuffer;
}

void window_present(window_t *base)
{
    linux_wayland_window_t *window = CONTAINER_OF(base, linux_wayland_window_t, base);
    linux_wayland_buffer_t *slot = window->current;
    if (NULL == slot) {
        return;
    }

    if (NULL == window->frame_callback) {
        window->frame_callback = wl_surface_frame(window->surface);
        wl_callback_add_listener(window->frame_callback, &frame_listener, window);
    }
    wl_surface_attach(window->surface, slot->buffer, 0, 0);
    wl_surface_damage_buffer(window->surface, 0, 0, slot->framebuffer.width,
                             slot->framebuffer.height);
    wl_surface_commit(window->surface);
    wl_display_flush(window->display);

    slot->busy = true;
    window->current = NULL;
}

void window_poll_events(window_t *base)
{
    linux_wayland_window_t *window = CONTAINER_OF(base, linux_wayland_window_t, base);
    struct wl_display *display = window->display;

    while (0 != wl_display_prepare_read(display)) {
        wl_display_dispatch_pending(display);
    }
    wl_display_flush(display);

    struct pollfd pfd = { .fd = wl_display_get_fd(display), .events = POLLIN };
    if (poll(&pfd, 1, 0) > 0) {
        wl_display_read_events(display);
    } else {
        wl_display_cancel_read(display);
    }

    if (-1 == wl_display_dispatch_pending(display)) {
        base->should_close = true;
    }
}

void window_wait_events(window_t *base)
{
    linux_wayland_window_t *window = CONTAINER_OF(base, linux_wayland_window_t, base);
    if (-1 == wl_display_dispatch(window->display)) {
        base->should_close = true;
    }
}
